function countNicePairs(nums) {
  const rev = x => Number(String(x).split('').reverse().join(''));
  let total = 0;
  for (let i = 0; i < nums.length; i++) {
    for (let j = i + 1; j < nums.length; j++) {
      if (nums[i] + rev(nums[j]) === nums[j] + rev(nums[i])) total++;
    }
  }
  return total % 1000000007;
}

