function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 8);
  const pick = () => {
    const r = rand();
    // Short numbers and palindromes share differences often, so nice pairs are common.
    if (r < 0.35) return Math.floor(rand() * (size === 'large' ? 1000 : 60));
    if (r < 0.55) {
      const half = String(1 + Math.floor(rand() * 9999));
      return Number(half + half.split('').reverse().join('').slice(rand() < 0.5 ? 1 : 0));
    }
    if (r < 0.65) return rand() < 0.5 ? 1000000000 : 0;
    return Math.floor(rand() * 1000000001);
  };
  return [Array.from({ length: n }, pick)];
}
